import{_ as e,o as t,c as r,a4 as s}from"./chunks/framework.vfuf0Qr8.js";const l="/assets/%E7%BD%91%E9%A1%B5%E9%A5%AE%E6%B0%B4%E8%AE%B0%E5%BD%95.7N_3_D9M.png",b=JSON.parse('{"title":"一起喝水吧：我做了一个无感记录每天饮水的杯垫","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://blob.suilice.xyz/pages/explore/share/%E5%96%9D%E5%90%A7%E5%96%9D%E5%90%A7-%E6%9D%AF%E5%9E%AB%E5%BC%80%E5%8F%91%E8%AE%B0%E5%BD%95"}]]},"headers":[],"relativePath":"pages/explore/share/喝吧喝吧-杯垫开发记录.md","filePath":"pages/explore/share/喝吧喝吧-杯垫开发记录.md","lastUpdated":1794479848000}'),n={name:"pages/explore/share/喝吧喝吧-杯垫开发记录.md"};function i(o,a,d,p,g,c){return t(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="一起喝水吧-我做了一个无感记录每天饮水的杯垫" tabindex="-1">一起喝水吧：我做了一个无感记录每天饮水的杯垫 <a class="header-anchor" href="#一起喝水吧-我做了一个无感记录每天饮水的杯垫" aria-label="Permalink to &quot;一起喝水吧：我做了一个无感记录每天饮水的杯垫&quot;">​</a></h1><p>工作间隙喝了两口水，想要记录下喝了多少，一天喝了几次？如果每次都拿起手机或者点开软件手动记录，数据既不准确，姿势也一点都不优雅。</p><p>每天有开不完的会、做不完的工作，计划的每天八杯水总会被扔在脑后。</p><p>于是我做了**「一起喝水吧」**杯垫：给常用的杯子称一次空重，后续无论是向杯子里加水、喝水，不用自己亲自动手，每时每刻都有一个小助手在后台帮你进行记录。如果没有完成目标，你也可以设置弱提醒和强提醒进行通知。</p><p>初版原型与网页端记录页面如下：</p><p><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/6575b118856ba94c9c5f6d99d2336a64.jpg" alt="6575b118856ba94c9c5f6d99d2336a64"></p><p><img src="'+l+'" alt="image-20261112165404481"></p><h2 id="现有功能" tabindex="-1">现有功能 <a class="header-anchor" href="#现有功能" aria-label="Permalink to &quot;现有功能&quot;">​</a></h2><p><span class="VPBadge" style="padding:0 .55em;border-radius:.35em;background:var(--vp-c-green-soft, #eaf4ec);color:var(--vp-c-green-1, #256249);">记录</span> <strong>杯子放回去，这一口就记上了</strong> 不用估毫升数，也不用拿手机打卡。上午用水杯，下午换茶杯，双击杯垫按钮切换，两只杯子各记各的。</p><p><span class="VPBadge" style="padding:0 .55em;border-radius:.35em;background:var(--vp-c-warning-soft, #fbf0dc);color:var(--vp-c-warning-1, #825216);">提醒</span> <strong>忙起来忘了喝水，让杯垫提醒我</strong> 想轻轻提醒一下，可以用软件通知。忙起来顾不上看通知，也可以让桌上的杯垫亮屏、震动。</p><p><span class="VPBadge" style="padding:0 .55em;border-radius:.35em;background:var(--vp-c-green-soft, #eaf4ec);color:var(--vp-c-green-1, #256249);">查看</span> <strong>电脑和手机，哪里都能看</strong> 坐在工位上，可以用网页、Mac 或 Windows 客户端看饮水记录。通勤路上用手机看，还能把今天的饮水量放在桌面卡片上更显眼。</p><p><strong>换个地方用：</strong> 换了 Wi-Fi，可以给杯垫重新配网；要换账号，可以快速解绑再绑定。</p><h2 id="后续-陪伴体系-构建-ing" tabindex="-1">后续：陪伴体系（构建 ing） <a class="header-anchor" href="#后续-陪伴体系-构建-ing" aria-label="Permalink to &quot;后续：陪伴体系（构建 ing）&quot;">​</a></h2><p>如果你恰好有一个志同道合的搭子，恰好还想和你一起分享记录每天饮水记录，那你们两个的杯垫就可以进行配对绑定～你可以类比理解为现实中的情侣空间，绑定后：</p><ul><li><p>你可以选择是否和对方分享你喝的每一次记录。</p></li><li><p>可以约定一个每天饮水量、间隔时间，当没有完成目标时可以通过杯垫和软件提醒对方。</p></li><li><p>和你的搭子一起用每天的饮水喂养一只爱喝水的健康小猫／小狗，也可以是一盆每天都在生长的绿植。</p></li></ul><h2 id="如何使用" tabindex="-1">如何使用 <a class="header-anchor" href="#如何使用" aria-label="Permalink to &quot;如何使用&quot;">​</a></h2><ol><li><strong>通电、登录。</strong> 给杯垫接上电源，打开手机或电脑访问网页，在网页上注册或登录账号。</li><li><strong>连接杯垫。</strong> 杯垫未绑定的时候会自动打开绑定蓝牙，在网页上点击「添加杯垫」，页面会请求蓝牙权限去寻找杯垫，选中设备后，按系统提示与杯垫显示屏上的绑定码完成蓝牙配对。</li><li><strong>连上 Wi-Fi。</strong> 杯垫绑定完成后，选择 2.4 GHz Wi-Fi，输入密码，等待杯垫连网并绑定到自己的账号。</li><li><strong>让杯垫记住空杯。</strong> 在「杯垫设置 → 我的杯子」中添加杯子、起个名字。先把杯垫腾空，再开始称量；按提示放上空杯，静置至少 3 秒后保存。</li><li><strong>喝第一口。</strong> 往杯里加水，放回杯垫，等重量稳定。接下来，拿起喝水、再放回去，记录就有了。</li></ol><p>一次绑定，后续只需通电就能无感记录；后续想要换无线网、换账号，只需按照 web 页面说明操作即可，简单方便。</p><h2 id="附录-饮水计算与部分客户端截图" tabindex="-1">附录：饮水计算与部分客户端截图 <a class="header-anchor" href="#附录-饮水计算与部分客户端截图" aria-label="Permalink to &quot;附录：饮水计算与部分客户端截图&quot;">​</a></h2><h3 id="饮水计算" tabindex="-1">饮水计算？ <a class="header-anchor" href="#饮水计算" aria-label="Permalink to &quot;饮水计算？&quot;">​</a></h3><p>杯垫比较的是同一只杯子拿起前、重新放稳后的重量。杯子变轻了，因为不同饮品密度不同，目前只按清水估算少了多少水：<strong>1 克水约等于 1 毫升</strong>。后面计划每只杯子都能单独设置饮品密度，增加自由度。</p><h3 id="安卓和mac客户端" tabindex="-1">安卓和mac客户端 <a class="header-anchor" href="#安卓和mac客户端" aria-label="Permalink to &quot;安卓和mac客户端&quot;">​</a></h3><p><strong>安卓｜看今天的进度</strong> 喝了几次、补了多少水，都在手机上。 <img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/867de2059e08567fee48451baadc2901.jpg" alt="867de2059e08567fee48451baadc2901" style="zoom:33%;"></p><table tabindex="0"><thead><tr><th style="text-align:left;">Mac｜瞄一眼最近一口</th><th style="text-align:left;">Mac｜选个桌面小伙伴</th></tr></thead><tbody><tr><td style="text-align:left;">点开菜单栏，就能看上次几点喝、喝了多少。</td><td style="text-align:left;">挑一个陪伴形象，也可以在这里开关喝水提醒。</td></tr><tr><td style="text-align:left;"><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20261112182625675.png" alt="image-20261112182625675"></td><td style="text-align:left;"><img src="https://cdn.jsdelivr.net/gh/scattter/blogweb/images/image-20261112182818391.png" alt="image-20261112182818391" style="zoom:67%;"></td></tr></tbody></table>',24)])])}const m=e(n,[["render",i]]);export{b as __pageData,m as default};
